def summarize(rows):
    passed = 0
    elapsed = 0.0
    for row in rows:
        elapsed += row["elapsed_s"]
        if row["status"] == "pass":
            passed += 1
    return {"passed": passed, "elapsed_s": elapsed, "passes_per_hour": passed * 3600 / elapsed if elapsed > 0 else None}

def summarize(rows):
    passed = sum(1 for r in rows if r["status"] == "pass")
    elapsed = sum(r["elapsed_s"] for r in rows if r["status"] == "pass")
    return {"passed": passed, "elapsed_s": elapsed, "passes_per_hour": passed * 3600 / elapsed if elapsed else None}

def admissible(receipt, batch, output):
    ranks = receipt.get("ranks", [])
    world = receipt.get("world_size", 0)
    if receipt.get("status") != "completed" or not isinstance(world, int) or isinstance(world, bool) or world <= 0:
        return False
    if len(ranks) != world or sorted(r["rank"] for r in ranks) != list(range(world)):
        return False
    return all(r["native_batch"] == batch and r["outputs"] and all(n == output for n in r["outputs"]) for r in ranks)
